-- {"query": "1957.sql", "dataset": "stackoverflow", "version": "v1.2", "prompt": "p1", "model": "gpt-4.1-mini", "temperature": 1.9, "max_tokens": 16384, "reasoning": "minimal", "input_tokens": 2027, "output_tokens": 3095} 
WITH OwnerStats AS (
  SELECT
    u.Id AS UserId,
    u.DisplayName,
    u.Reputation,
    COUNT(p.Id) FILTER (WHERE p.PostTypeId = 1) AS TotalQuestions,
    COUNT(p.Id) FILTER (WHERE p.PostTypeId = 2) AS TotalAnswers,
    COALESCE(SUM(p.Score), 0) AS TotalPostScore,
    AVG(CASE WHEN p.PostTypeId IN (1,2) THEN p.Score ELSE NULL END) AS AvgPostScore,
    COALESCE(SUM(p.ViewCount), 0) AS SumViewCounts,
    count(b.Id) FILTER (WHERE b.Class = 1) AS GoldBadges,
    count(b.Id) FILTER (WHERE b.Class = 2) AS SilverBadges,
    count(b.Id) FILTER (WHERE b.Class = 3) AS BronzeBadges
  FROM Users u
  LEFT JOIN Posts p ON p.OwnerUserId = u.Id
  LEFT JOIN Badges b ON b.UserId = u.Id
  WHERE u.DisplayName IS NOT NULL
  GROUP BY u.Id, u.DisplayName, u.Reputation
